('Philippines', 'National Capital Region', 'Talipapa')
) AS x(pays, region, ville)
JOIN pays p ON p.nom = x.pays
JOIN region r ON r.id_pays = p.id AND r.nom = x.region
ON CONFLICT (nom, id_region) DO NOTHING;

