-- CONTROLES
SELECT
  (SELECT COUNT(*) FROM pays) AS pays,
  (SELECT COUNT(*) FROM region) AS regions,
  (SELECT COUNT(*) FROM ville) AS villes;

-- Madagascar doit exister comme pays, mais rester vide avant la migration 18.
SELECT
  p.nom AS pays,
  COUNT(DISTINCT r.id) AS regions,
  COUNT(DISTINCT v.id) AS villes
FROM pays p
LEFT JOIN region r ON r.id_pays = p.id
LEFT JOIN ville v ON v.id_region = r.id
WHERE p.nom = 'Madagascar'
GROUP BY p.nom;
